package com.memetrade.shared.solana;

import static org.assertj.core.api.Assertions.assertThat;

import com.fasterxml.jackson.databind.JsonNode;
import com.memetrade.realexecution.domain.solana.Ed25519Check;
import com.memetrade.realexecution.domain.solana.WireTransaction;
import java.util.List;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;

/**
 * Step 3 of the U4 (U4-NFR1.1, deviation of Q2): the OWN Base58 and the native Ed25519 of the api agree with the common
 * vectors generated by the SDK in test scope; the TxSigner runs the same vectors against its own reader.
 */
@Tag("u4-real-execution")
class SolanaVectorConformanceTest {

    private final JsonNode vectors = SolanaVectors.load();

    @Test
    void theOwnBase58EncodesAndDecodesEveryVector() {
        for (JsonNode vector : vectors.path("base58")) {
            byte[] bytes = SolanaVectors.hex(vector.path("hex").asText());
            String text = vector.path("base58").asText();

            assertThat(Base58Codec.encode(bytes)).as(text).isEqualTo(text);
            assertThat(Base58Codec.decode(text, bytes.length)).as(text).isEqualTo(bytes);
        }
    }

    @Test
    void theNativeEd25519VerifiesEverySignatureOfTheSdk() {
        for (JsonNode vector : vectors.path("signatures")) {
            byte[] key = Base58Codec.decode(vector.path("publicKey").asText(), 32);
            byte[] message = SolanaVectors.hex(vector.path("messageHex").asText());
            byte[] signature = Base58Codec.decode(vector.path("signature").asText(), 64);

            assertThat(Ed25519Check.verify(key, message, signature)).isTrue();
            byte[] tampered = message.clone();
            tampered = tampered.length == 0 ? new byte[] {1} : flip(tampered);
            assertThat(Ed25519Check.verify(key, tampered, signature)).isFalse();
        }
    }

    @Test
    void everySignatureOfTheSignedVectorTransactionsVerifiesOverItsMessage() {
        for (SolanaVectors.MessageVector vector : SolanaVectors.messages()) {
            WireTransaction transaction = WireTransaction.decodeBase64(vector.signedTransactionBase64());

            assertThat(transaction.messageBytes()).as(vector.name()).isEqualTo(vector.legacyMessage());
            List<byte[]> signatures = transaction.signatures();
            assertThat(signatures).hasSameSizeAs(vector.signers());
            for (int i = 0; i < signatures.size(); i++) {
                assertThat(Ed25519Check.verify(
                                Base58Codec.decode(vector.signers().get(i), 32),
                                transaction.messageBytes(),
                                signatures.get(i)))
                        .as(vector.name() + " signer " + i)
                        .isTrue();
            }
        }
    }

    @Test
    void aBadKeyOrABadSignatureNeverVerifies() {
        JsonNode vector = vectors.path("signatures").get(1);
        byte[] key = Base58Codec.decode(vector.path("publicKey").asText(), 32);
        byte[] message = SolanaVectors.hex(vector.path("messageHex").asText());
        byte[] signature = Base58Codec.decode(vector.path("signature").asText(), 64);

        assertThat(Ed25519Check.verify(new byte[31], message, signature)).isFalse();
        assertThat(Ed25519Check.verify(key, message, new byte[63])).isFalse();
        assertThat(Ed25519Check.verify(key, message, flip(signature))).isFalse();
        assertThat(Ed25519Check.verify(null, message, signature)).isFalse();
    }

    private static byte[] flip(byte[] bytes) {
        byte[] copy = bytes.clone();
        copy[copy.length - 1] ^= 0x01;
        return copy;
    }
}
